package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="billing_runs") public class BillingRun {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="billing_period_id") private BillingPeriod billingPeriod; @Column(nullable=false,length=20) private String status;
 @Column(name="charge_count",nullable=false) private int chargeCount; @Column(nullable=false,precision=19,scale=4) private BigDecimal subtotal=BigDecimal.ZERO; @Column(name="tax_total",nullable=false,precision=19,scale=4) private BigDecimal taxTotal=BigDecimal.ZERO; @Column(name="grand_total",nullable=false,precision=19,scale=4) private BigDecimal grandTotal=BigDecimal.ZERO;
 @Column(name="started_at",nullable=false) private Instant startedAt; @Column(name="completed_at") private Instant completedAt; @Column(name="failure_reason",length=500) private String failureReason; @PrePersist void create(){startedAt=Instant.now();}
 public UUID getId(){return id;} public BillingPeriod getBillingPeriod(){return billingPeriod;} public void setBillingPeriod(BillingPeriod v){billingPeriod=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public int getChargeCount(){return chargeCount;} public void setChargeCount(int v){chargeCount=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} public BigDecimal getTaxTotal(){return taxTotal;} public void setTaxTotal(BigDecimal v){taxTotal=v;} public BigDecimal getGrandTotal(){return grandTotal;} public void setGrandTotal(BigDecimal v){grandTotal=v;} public Instant getStartedAt(){return startedAt;} public Instant getCompletedAt(){return completedAt;} public void setCompletedAt(Instant v){completedAt=v;} public String getFailureReason(){return failureReason;} public void setFailureReason(String v){failureReason=v;}
}
